word-frequency:
def word_frequency(words):
    out={}
    for w in words: out[w]=out.get(w,0)+1
    return out

first-divisible:
def first_divisible(start,divisor):
    while start%divisor!=0: start+=1
    return start

flatten-matrix:
def flatten(matrix):
    result=[]
    for row in matrix:
        for v in row:result.append(v)
    return result

is-prime:
def is_prime(n):
    if n<2:return False
    for d in range(2,int(n**0.5)+1):
        if n%d==0:return False
    return True

recursive-sum:
def recursive_sum(numbers):
    if not numbers:return 0
    return numbers[0]+recursive_sum(numbers[1:])

