days-between:
from datetime import datetime
def days_between(date1,date2):
    fmt='%Y-%m-%d'
    return abs((datetime.strptime(date2,fmt)-datetime.strptime(date1,fmt)).days)

safe-divide:
def safe_divide(a,b):
    try:return a/b
    except ZeroDivisionError:return None

write-read-file:
def write_and_read(path,text):
    with open(path,'w',encoding='utf-8') as f:f.write(text)
    with open(path,'r',encoding='utf-8') as f:return f.read()

double-decorator:
def double_result(func):
    def wrapper(*args,**kwargs):return 2*func(*args,**kwargs)
    return wrapper
@double_result
def add(a,b):return a+b

palindrome-clean:
def is_palindrome(text):
    s=''.join(c.casefold() for c in text if c.isalnum())
    return s==s[::-1]

cart-total:
def cart_total(cart,prices,discount=0):
    total=sum(qty*prices[name] for name,qty in cart.items())
    return round(total*(1-discount/100),2)
